/* @lc app=leetcode id=1801 lang=kotlin */ class Solution { fun m(own: java.util.PriorityQueue<IntArray>, opp: java.util.PriorityQueue<IntArray>, p: Int, a: Int, buy: Boolean) = generateSequence(a) { r -> opp.peek()?.takeIf { r > 0 && (if (buy) it[0] <= p else it[0] >= p) }?.let { top -> minOf(r, top[1]).also { x -> top[1] -= x }.also { if (top[1] == 0) opp.poll() }.let { r - it } } }.last().let { if (it > 0) own.add(intArrayOf(p, it)) } fun getNumberOfBacklogOrders(orders: Array<IntArray>): Int = java.util.PriorityQueue<IntArray>(compareByDescending<IntArray> { it[0] }).let { buy -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).let { sell -> orders.forEach { (p, a, t) -> if (t == 0) m(buy, sell, p, a, true) else m(sell, buy, p, a, false) }.let { ((buy + sell).sumOf { it[1].toLong() } % 1_000_000_007).toInt() } } } }